import type { PayloadTypes } from '$lib/payload-types'
import { config } from '../../config/config'
import { page } from '$app/state'

export const getLocalizationByHostname = (url: URL): PayloadTypes.Config['locale'] => {
	const locale = Object.keys(config.localization.urls).find((locale) =>
		config.localization.urls[locale as PayloadTypes.Config['locale']].some((hostname) =>
			url.href.startsWith(hostname)
		)
	) as PayloadTypes.Config['locale'] | undefined
	return locale || 'nl'
}

export const getLocalization = () => {
	return getLocalizationByHostname(page.url)
}

import { PayloadTypes } from '$lib/payload-types'
import { PayloadSDK } from '@payloadcms/sdk'
import { config } from '../../config/config'
import { getLocalizationByHostname } from '$lib/localization/getLocalizationByUrl'
import { browser } from '$app/environment'

type GetSdkParams = {
	fetchFn: typeof fetch
	parentUrl: URL
	credentials?: RequestCredentials
}

const addLocaleToUrl = (incoming: string | URL | Request, parentUrl: URL): URL | Request => {
	const locale = getLocalizationByHostname(parentUrl)
	if (incoming instanceof URL || typeof incoming === 'string') {
		const url = new URL(incoming)
		url.searchParams.set('locale', locale)
		return url
	}

	const url = new URL(incoming.url)
	url.searchParams.set('locale', locale)

	return new Request(url.toString(), incoming)
}

export const payloadSdk = ({ fetchFn, parentUrl, credentials = 'include' }: GetSdkParams) => {
	const locale = getLocalizationByHostname(parentUrl)
	const defaultUrl = browser ? config.urls.default[locale] : config.urls.internal

	return new PayloadSDK<PayloadTypes.Config>({
		baseURL: `${defaultUrl}/api`,
		fetch: async (url, init?) => {
			url = addLocaleToUrl(url, parentUrl)
			const headers = new Headers(init?.headers)
			headers.set('Force-Locale', '1')
			headers.set('Frontend', '1')
			const response = await fetchFn(url, {
				...init,
				credentials,
				headers
			})

			return response
		}
	})
}

import { PUBLIC_PAYLOAD_URL } from '$env/static/public'
import { PayloadSDK } from '@payloadcms/sdk'

type CreatePayloadClientOptions = {
	fetchFn?: typeof fetch
	baseUrl?: string
	token?: string
}

export const createPayloadClient = ({ fetchFn = fetch, baseUrl, token }: CreatePayloadClientOptions) => {
	const baseURL = baseUrl || PUBLIC_PAYLOAD_URL || 'http://localhost:4000'

	return new PayloadSDK({
		baseURL: `${baseURL}/api`,
		fetch: async (url, init) => {
			const headers = new Headers(init?.headers)
			if (token) {
				headers.set('Authorization', `Bearer ${token}`)
			}
			return fetchFn(url, { ...init, credentials: 'include', headers })
		},
	})
}

